const body = $json.body || $json || {};

return [
  {
    json: {
      action: String(body.action || '').trim(),
      requested_by: body.requested_by || '',
      requested_by_name: body.requested_by_name || '',
      actor: body.actor || {},
      operacion: body.operacion || {},
      pagos_programados: body.pagos_programados || [],
    },
  },
];

function norm(v) { return String(v == null ? '' : v).trim(); }
function toNumber(value) {
  let s = String(value == null ? '' : value);
  s = s.split('Bs.').join('').split('Bs').join('').split(' ').join('').split(',').join('');
  const n = Number(s);
  return Number.isFinite(n) ? n : 0;
}

const operaciones = $('Get row(s) - Operaciones').all().map(i => i.json).filter(r => r.operacion_id || r.cliente_id || r.descripcion_operacion);

const pagosMap = {};
for (const it of $('Get row(s) - Pagos List').all()) {
  const r = it.json;
  if (r && r.pago_id && !pagosMap[r.pago_id]) pagosMap[r.pago_id] = r;
}
const pagos = Object.keys(pagosMap).map(k => pagosMap[k]);

const depositosMap = {};
for (const it of $('Get row(s) - Depositos List').all()) {
  const r = it.json;
  if (r && r.deposito_id && !depositosMap[r.deposito_id]) depositosMap[r.deposito_id] = r;
}
const depositos = Object.keys(depositosMap).map(k => depositosMap[k]);

const pagosByOp = {};
for (const p of pagos) {
  const id = norm(p.operacion_id);
  if (!id) continue;
  if (!pagosByOp[id]) pagosByOp[id] = [];
  pagosByOp[id].push(p);
}

const depositoOps = {};
for (const d of depositos) {
  const id = norm(d.operacion_id);
  if (id) depositoOps[id] = true;
}

const today = new Date();
today.setHours(0, 0, 0, 0);

function estadoCobro(opPagos) {
  if (!opPagos || !opPagos.length) return 'Sin plan';
  let totalProg = 0;
  let totalPag = 0;
  let vencido = false;
  for (const p of opPagos) {
    const prog = toNumber(p.monto_programado);
    const pag = toNumber(p.monto_pagado_acumulado);
    const saldo = toNumber(p.saldo_pago);
    totalProg += prog;
    totalPag += pag;
    const estado = norm(p.estado_pago);
    const pendiente = saldo > 0 && estado !== 'Pagado';
    if (pendiente && p.fecha_programada) {
      const due = new Date(String(p.fecha_programada) + 'T00:00:00');
      if (!isNaN(due.getTime()) && due < today) vencido = true;
    }
  }
  if (vencido) return 'Vencido';
  if (totalPag <= 0) return 'Pendiente';
  if (totalProg > 0 && totalPag >= totalProg - 0.05) return 'Pagado';
  return 'Cobro parcial';
}

function normalizeEstado(value) {
  const current = String(value == null ? '' : value).trim();
  if (current === 'Vigente' || current === 'Cobro parcial') return 'Vigente';
  if (current === 'Cerrada' || current === 'No aprobada' || current === 'No aceptada' || current === 'Anulada' || current === 'Perdida') return 'Cerrada';
  return 'Cotización';
}

const enriched = operaciones.map(op => {
  const id = norm(op.operacion_id);
  const opPagos = pagosByOp[id] || [];
  const tienePagos = opPagos.length > 0;
  const tieneDepositos = depositoOps[id] === true;
  const estadoNorm = normalizeEstado(op.estado_operacion);
  let estadoEfectivo = estadoNorm;
  let requiereRegularizacion = false;
  if ((tienePagos || tieneDepositos) && estadoNorm === 'Cotización') {
    estadoEfectivo = 'Vigente';
    requiereRegularizacion = true;
  }
  return Object.assign({}, op, {
    estado_operacion: estadoEfectivo,
    tiene_pagos: tienePagos,
    tiene_depositos: tieneDepositos,
    estado_cobro: estadoCobro(opPagos),
    requiere_regularizacion: requiereRegularizacion,
  });
});

const actor = $('Code - Normalize Action').first().json.actor || {};
const role = String(actor.role || '').trim();
const actorEmail = String(actor.email || '').trim().toLowerCase();
const actorName = String(actor.name || '').trim().toLowerCase();

let visibles = enriched;
if (role !== 'admin') {
  visibles = enriched.filter(function (op) {
    const cb = String(op.created_by || '').trim().toLowerCase();
    if (cb) return cb === actorEmail;
    return String(op.responsable || '').trim().toLowerCase() === actorName;
  });
}

return [{ json: { ok: true, message: 'Operaciones obtenidas correctamente.', operaciones: visibles } }];

const payload = $('Code - Normalize Action').first().json;

const operacion = payload.operacion || {};
const pagosInput = payload.pagos_programados || [];

const operacionesRows = $('Get row(s) - Operaciones Create')
  .all()
  .map(item => item.json)
  .filter(row => row.operacion_id);

const pagosRows = $('Get row(s) - Pagos Create')
  .all()
  .map(item => item.json)
  .filter(row => row.pago_id);

const clientesRows = $('Get row(s) - Clientes Create')
  .all()
  .map(item => item.json)
  .filter(row => row.cliente_id);

function nextId(rows, field, prefix) {
  let max = 0;
  const pre = prefix + '-';
  for (const row of rows) {
    const value = String(row[field] || '');
    if (value.indexOf(pre) === 0) {
      const number = parseInt(value.slice(pre.length), 10);
      if (Number.isFinite(number) && number > max) max = number;
    }
  }
  return prefix + '-' + String(max + 1).padStart(4, '0');
}

function toNumber(value) {
  const num = Number(value || 0);
  return Number.isFinite(num) ? num : 0;
}

function normalizeEstado(value) {
  const current = String(value || '').trim();
  if (current === 'Vigente' || current === 'Cobro parcial') return 'Vigente';
  if (current === 'Cerrada' || current === 'No aprobada' || current === 'No aceptada' || current === 'Anulada' || current === 'Perdida') return 'Cerrada';
  return 'Cotización';
}

if (!operacion.cliente_id) {
  return [{ json: { ok: false, message: 'Debe seleccionar un cliente.' } }];
}

const clienteRow = clientesRows.find(c => String(c.cliente_id || '').trim() === String(operacion.cliente_id || '').trim());
if (!clienteRow) {
  return [{ json: { ok: false, message: 'El cliente seleccionado no existe.' } }];
}
const tipoEmpresa = String(clienteRow.tipo_cliente || '').trim();

if (!String(operacion.descripcion_operacion || '').trim()) {
  return [{ json: { ok: false, message: 'La descripción de la operación es obligatoria.' } }];
}

const estado = normalizeEstado(operacion.estado_operacion);
const estadoCreate = estado === 'Vigente' ? 'Vigente' : 'Cotización';
const esVigente = estadoCreate === 'Vigente';
const montoTotal = toNumber(operacion.monto_total_comprometido);

let pagosValidos = [];

if (esVigente) {
  if (!montoTotal || montoTotal <= 0) {
    return [{ json: { ok: false, message: 'El monto debe ser mayor a 0 para una operación vigente.' } }];
  }
  if (!pagosInput.length) {
    return [{ json: { ok: false, message: 'Debe existir al menos un pago programado para una operación vigente.' } }];
  }
  const totalPorcentaje = pagosInput.reduce((sum, p) => sum + toNumber(p.porcentaje_programado), 0);
  if (Math.abs(totalPorcentaje - 100) > 0.01) {
    return [{ json: { ok: false, message: 'La suma de porcentajes del plan de pagos debe ser 100%.' } }];
  }
  const totalPagos = pagosInput.reduce((sum, p) => sum + toNumber(p.monto_programado), 0);
  if (Math.abs(totalPagos - montoTotal) > 0.05) {
    return [{ json: { ok: false, message: 'La suma de montos programados debe igualar el monto total.' } }];
  }
  pagosValidos = pagosInput;
}

const operacionId = nextId(operacionesRows, 'operacion_id', 'OP');

let pagoMax = 0;
for (const row of pagosRows) {
  const value = String(row.pago_id || '');
  if (value.indexOf('PAG-') === 0) {
    const number = parseInt(value.slice(4), 10);
    if (Number.isFinite(number) && number > pagoMax) pagoMax = number;
  }
}

const preparedOperacion = {
  operacion_id: operacionId,
  cliente_id: operacion.cliente_id || '',
  fecha_registro: operacion.fecha_registro || new Date().toISOString().slice(0, 10),
  descripcion_operacion: String(operacion.descripcion_operacion || '').trim(),
  cantidad: operacion.cantidad || '',
  tipo_operacion: operacion.tipo_operacion || '',
  tipo_empresa: tipoEmpresa,
  responsable: operacion.responsable || '',
  estado_operacion: estadoCreate,
  nivel_certeza: operacion.nivel_certeza || '',
  probabilidad: operacion.probabilidad || '',
  modalidad_pago: '',
  monto_total_comprometido: operacion.monto_total_comprometido || '',
  monto_total_ponderado: operacion.monto_total_ponderado || '',
  vigencia_desde: operacion.vigencia_desde || '',
  vigencia_hasta: operacion.vigencia_hasta || '',
  proximo_hito: '',
  fecha_proximo_hito: '',
  observaciones: operacion.observaciones || '',
  estado_general: operacion.estado_general || 'Activo',
  created_by: operacion.created_by || '',
  created_by_name: operacion.created_by_name || '',
  created_at: operacion.created_at || new Date().toISOString(),
  updated_by: '',
  updated_by_name: '',
  updated_at: '',
};

const pagosProgramados = pagosValidos.map((pago, index) => {
  pagoMax += 1;
  const montoProgramado = toNumber(pago.monto_programado);
  return {
    pago_id: 'PAG-' + String(pagoMax).padStart(4, '0'),
    operacion_id: operacionId,
    cliente_id: operacion.cliente_id || '',
    numero_pago: pago.numero_pago || index + 1,
    concepto_pago: pago.concepto_pago || ('Pago ' + (index + 1)),
    porcentaje_programado: pago.porcentaje_programado || '',
    monto_programado: montoProgramado,
    fecha_programada: pago.fecha_programada || '',
    estado_pago: pago.estado_pago || 'Pendiente',
    monto_pagado_acumulado: 0,
    saldo_pago: montoProgramado,
    fecha_ultimo_pago: '',
    modalidad_pago: '',
    observaciones: '',
    created_by: operacion.created_by || '',
    created_by_name: operacion.created_by_name || '',
    created_at: operacion.created_at || new Date().toISOString(),
    updated_by: '',
    updated_by_name: '',
    updated_at: '',
  };
});

return [{
  json: {
    ok: true,
    message: 'Operación preparada correctamente.',
    operacion: preparedOperacion,
    pagos_programados: pagosProgramados,
  },
}];

const pagos = $('Code - Prepare Create Operacion').first().json.pagos_programados || [];

return pagos.map((pago) => ({
  json: pago,
}));

