const payload = $('Code - Normalize Action').first().json;
const operacion = payload.operacion || {};
const pagosInput = payload.pagos_programados || [];

function norm(v) { return String(v == null ? '' : v).trim(); }

function toNumber(value) {
  let s = String(value == null ? '' : value);
  s = s.split('Bs.').join('').split('Bs').join('').split(' ').join('').split(',').join('');
  const n = Number(s);
  return Number.isFinite(n) ? n : 0;
}

function normalizeEstado(value) {
  const current = norm(value);
  if (current === 'Vigente' || current === 'Cobro parcial') return 'Vigente';
  if (current === 'Cerrada' || current === 'No aprobada' || current === 'No aceptada' || current === 'Anulada' || current === 'Perdida') return 'Cerrada';
  return 'Cotización';
}

const operacionesRows = $('Get row(s) - Operaciones Update').all().map(i => i.json).filter(r => r.operacion_id);
const pagosRows = $('Get row(s) - Pagos Update').all().map(i => i.json).filter(r => r.pago_id);
const depositosRows = $('Get row(s) - Depositos Update').all().map(i => i.json).filter(r => r.deposito_id);
const clientesRows = $('Get row(s) - Clientes Update').all().map(i => i.json).filter(r => r.cliente_id);

const operacionId = norm(operacion.operacion_id);
if (!operacionId) {
  return [{ json: { ok: false, message: 'Falta el identificador de la operación.' } }];
}

const targetRow = operacionesRows.find(r => norm(r.operacion_id) === operacionId);
if (!targetRow) {
  return [{ json: { ok: false, message: 'No se encontró la operación a actualizar.' } }];
}

const rowNumber = targetRow.row_number || targetRow.rowNumber || targetRow.__rowNumber || '';

const clienteIdEfectivo = String(operacion.cliente_id || targetRow.cliente_id || '').trim();
const clienteRow = clientesRows.find(c => String(c.cliente_id || '').trim() === clienteIdEfectivo);
if (!clienteRow) {
  return [{ json: { ok: false, message: 'El cliente seleccionado no existe.' } }];
}
const tipoEmpresa = String(clienteRow.tipo_cliente || '').trim();

const seenPagos = {};
let tienePagos = false;
for (const r of pagosRows) {
  if (norm(r.operacion_id) === operacionId) {
    const pid = norm(r.pago_id);
    if (pid && !seenPagos[pid]) { seenPagos[pid] = true; tienePagos = true; }
  }
}

const seenDepositos = {};
let tieneDepositos = false;
for (const r of depositosRows) {
  if (norm(r.operacion_id) === operacionId) {
    const did = norm(r.deposito_id);
    if (did && !seenDepositos[did]) { seenDepositos[did] = true; tieneDepositos = true; }
  }
}

const estadoNuevo = normalizeEstado(operacion.estado_operacion);

const montoNuevo = toNumber(operacion.monto_total_comprometido);
const montoActual = toNumber(targetRow.monto_total_comprometido);

if (tieneDepositos && Math.abs(montoNuevo - montoActual) > 0.05) {
  return [{ json: { ok: false, message: 'La operación tiene depósitos registrados; no se puede modificar el monto total.' } }];
}

let pagosToCreate = [];

// PUT (update) nunca crea pagos: el plan se crea al aprobar la cotización (activate).
if (false) {
  if (!montoNuevo || montoNuevo <= 0) {
    return [{ json: { ok: false, message: 'El monto debe ser mayor a 0 para una operación vigente.' } }];
  }
  if (!pagosInput.length) {
    return [{ json: { ok: false, message: 'Debe definir al menos un pago programado.' } }];
  }
  const totalPorcentaje = pagosInput.reduce((sum, p) => sum + toNumber(p.porcentaje_programado), 0);
  if (Math.abs(totalPorcentaje - 100) > 0.01) {
    return [{ json: { ok: false, message: 'La suma de porcentajes del plan de pagos debe ser 100%.' } }];
  }
  const totalPagos = pagosInput.reduce((sum, p) => sum + toNumber(p.monto_programado), 0);
  if (Math.abs(totalPagos - montoNuevo) > 0.05) {
    return [{ json: { ok: false, message: 'La suma de montos programados debe igualar el monto total.' } }];
  }

  let pagoMax = 0;
  for (const r of pagosRows) {
    const value = String(r.pago_id || '');
    if (value.indexOf('PAG-') === 0) {
      const number = parseInt(value.slice(4), 10);
      if (Number.isFinite(number) && number > pagoMax) pagoMax = number;
    }
  }

  pagosToCreate = pagosInput.map((pago, index) => {
    pagoMax += 1;
    const montoProgramado = toNumber(pago.monto_programado);
    return {
      pago_id: 'PAG-' + String(pagoMax).padStart(4, '0'),
      operacion_id: operacionId,
      cliente_id: operacion.cliente_id || targetRow.cliente_id || '',
      numero_pago: pago.numero_pago || index + 1,
      concepto_pago: pago.concepto_pago || ('Pago ' + (index + 1)),
      porcentaje_programado: pago.porcentaje_programado || '',
      monto_programado: montoProgramado,
      fecha_programada: pago.fecha_programada || '',
      estado_pago: pago.estado_pago || 'Pendiente',
      monto_pagado_acumulado: 0,
      saldo_pago: montoProgramado,
      fecha_ultimo_pago: '',
      modalidad_pago: operacion.modalidad_pago || '',
      observaciones: '',
      created_by: operacion.updated_by || operacion.created_by || '',
      created_by_name: operacion.updated_by_name || operacion.created_by_name || '',
      created_at: new Date().toISOString(),
      updated_by: '',
      updated_by_name: '',
      updated_at: '',
    };
  });
}

function pick(newVal, oldVal) {
  return (newVal === undefined || newVal === null || newVal === '') ? (oldVal || '') : newVal;
}

const updatedOperacion = {
  row_number: rowNumber,
  operacion_id: operacionId,
  cliente_id: operacion.cliente_id || targetRow.cliente_id || '',
  fecha_registro: pick(operacion.fecha_registro, targetRow.fecha_registro),
  descripcion_operacion: norm(operacion.descripcion_operacion) || targetRow.descripcion_operacion || '',
  cantidad: pick(operacion.cantidad, targetRow.cantidad),
  tipo_operacion: operacion.tipo_operacion || targetRow.tipo_operacion || '',
  tipo_empresa: tipoEmpresa,
  responsable: targetRow.responsable || operacion.responsable || '',
  estado_operacion: targetRow.estado_operacion || '',
  nivel_certeza: pick(operacion.nivel_certeza, targetRow.nivel_certeza),
  probabilidad: pick(operacion.probabilidad, targetRow.probabilidad),
  modalidad_pago: operacion.modalidad_pago || targetRow.modalidad_pago || '',
  monto_total_comprometido: pick(operacion.monto_total_comprometido, targetRow.monto_total_comprometido),
  monto_total_ponderado: pick(operacion.monto_total_ponderado, targetRow.monto_total_ponderado),
  vigencia_desde: (operacion.vigencia_desde === undefined || operacion.vigencia_desde === null) ? (targetRow.vigencia_desde || '') : operacion.vigencia_desde,
  vigencia_hasta: (operacion.vigencia_hasta === undefined || operacion.vigencia_hasta === null) ? (targetRow.vigencia_hasta || '') : operacion.vigencia_hasta,
  proximo_hito: targetRow.proximo_hito || '',
  fecha_proximo_hito: targetRow.fecha_proximo_hito || '',
  observaciones: (operacion.observaciones === undefined || operacion.observaciones === null) ? (targetRow.observaciones || '') : operacion.observaciones,
  estado_general: operacion.estado_general || targetRow.estado_general || 'Activo',
  created_by: targetRow.created_by || '',
  created_by_name: targetRow.created_by_name || '',
  created_at: targetRow.created_at || '',
  updated_by: operacion.updated_by || '',
  updated_by_name: operacion.updated_by_name || '',
  updated_at: operacion.updated_at || new Date().toISOString(),
};

return [{
  json: {
    ok: true,
    message: pagosToCreate.length ? 'Operación actualizada y plan de pagos creado.' : 'Operación actualizada correctamente.',
    operacion: updatedOperacion,
    pagos_programados: pagosToCreate,
    pagos_to_create: pagosToCreate.length > 0,
  },
}];

const pagos = $('Code - Prepare Update').first().json.pagos_programados || [];

return pagos.map((pago) => ({
  json: pago,
}));

