const operacion = $('Code - Normalize Action').first().json.operacion || {};
function norm(v) { return String(v == null ? '' : v).trim(); }
function normalizeEstado(value) {
  const current = norm(value);
  if (current === 'Vigente' || current === 'Cobro parcial') return 'Vigente';
  if (current === 'Cerrada' || current === 'No aprobada' || current === 'No aceptada' || current === 'Anulada' || current === 'Perdida') return 'Cerrada';
  return 'Cotización';
}

const operacionId = norm(operacion.operacion_id);
if (!operacionId) {
  return [{ json: { ok: false, message: 'Falta el identificador de la operación a cerrar.' } }];
}

const rows = $('Get row(s) - Operaciones Close').all().map(i => i.json).filter(r => r.operacion_id);
const targetRow = rows.find(r => norm(r.operacion_id) === operacionId);
if (!targetRow) {
  return [{ json: { ok: false, message: 'No se encontró la operación a cerrar.' } }];
}

const estadoActual = normalizeEstado(targetRow.estado_operacion);
if (estadoActual === 'Vigente') {
  return [{ json: { ok: false, message: 'No se puede cerrar una operación vigente desde este botón.' } }];
}
if (estadoActual === 'Cerrada') {
  return [{ json: { ok: false, message: 'La operación ya estaba cerrada.' } }];
}

const rowNumber = targetRow.row_number || targetRow.rowNumber || targetRow.__rowNumber || '';

const updatedOperacion = {
  row_number: rowNumber,
  operacion_id: operacionId,
  estado_operacion: 'Cerrada',
  updated_by: operacion.updated_by || '',
  updated_by_name: operacion.updated_by_name || '',
  updated_at: operacion.updated_at || new Date().toISOString(),
};

const operacionEnriquecida = Object.assign({}, targetRow, { estado_operacion: 'Cerrada', updated_by: updatedOperacion.updated_by, updated_by_name: updatedOperacion.updated_by_name, updated_at: updatedOperacion.updated_at });

return [{ json: { ok: true, message: 'Cotización cerrada correctamente.', operacion: updatedOperacion, operacion_enriquecida: operacionEnriquecida } }];
